const POLYFILL = '<script>/* chicheng-gate */ (function(){try{var c=window.crypto;if(!c||typeof c.randomUUID==="function")return;var u=function(){var b=new Uint8Array(16);c.getRandomValues(b);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;var h=[];for(var i=0;i<16;i++)h.push((b[i]+256).toString(16).slice(1));return h.slice(0,4).join("")+"-"+h.slice(4,6).join("")+"-"+h.slice(6,8).join("")+"-"+h.slice(8,10).join("")+"-"+h.slice(10,16).join("")};try{c.randomUUID=u}catch(e){try{Object.defineProperty(c,"randomUUID",{value:u,configurable:true,writable:true})}catch(e2){}}}catch(e){}})();</script>';

