const SettingsSchema = z.object({
  consented: z.boolean().default(false),
  remoteEnabled: z.boolean().default(false),
  dhcpAddress: z.string().default(""),
  mobileUi: z.boolean().default(true),
  frpcEnabled: z.boolean().default(false),
