      "content": "# chicheng-gate bundle patch
#
# Bind host + trust fence from the remoteAccess service (provided early by
# this plugin). webserver/connection MUST inject remoteAccess so the service
# resolves during their config interpolation.
- id: webserver
  inject:
    - webStartup
    - remoteAccess
  config:
    host: !!js ctx.remoteAccess.host
    port: !!js ctx.webStartup.port ?? 3080
- id: connection
  inject:
    - webRuntime
    - remoteAccess
  config:
    trustedHosts: !!js ctx.remoteAccess.trustedHosts
- id: web-runtime
  inject:
    - webStartup
    - remoteAccess
  config:
    printUrl: true
    surfaceContext: true
    trustedHosts: !!js ctx.remoteAccess.trustedHosts
- insert:
    - id: chicheng-gate
      name: 'chicheng-gate'
